import{af as t,z as a,J as i,ab as s}from"./chunks/framework.BnTFvF69.js";const c=JSON.parse('{"title":"Rate Limits","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"apis/rate-limits.md","filePath":"apis/rate-limits.md"}'),n={name:"apis/rate-limits.md"};function r(l,e,p,d,o,m){return a(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793279959000"},[...e[0]||(e[0]=[s(`<h1 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h1><p>All API requests can be rate limited and send a <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/429" target="_blank" rel="noreferrer">429 Too Many Requests</a> response.</p><p>All API responses can include the following headers to help you determine your current rate limit status:</p><table tabindex="0"><thead><tr><th>Header</th><th>Description</th><th>Source</th></tr></thead><tbody><tr><td>X-Ratelimit-Limit</td><td>The maximum number of requests that the consumer is permitted to make per rate limit window.</td><td>All</td></tr><tr><td>X-Ratelimit-Remaining</td><td>The number of requests remaining in the current rate limit window.</td><td>All</td></tr><tr><td>X-Ratelimit-Reset</td><td>The time at which the current rate limit window resets in UTC epoch seconds.</td><td>Application</td></tr><tr><td>X-Ratelimit-Window</td><td>Number of seconds of the window.</td><td>Edge</td></tr></tbody></table><p>The <code>Source</code> refers to the source of the rate limit. Rate limits will most commonly be set by the application, but may also be set by the edge.</p><p>Actual rate limits may vary depending on the API endpoint and vary depending on system loads.</p><p>For example, user authentication related endpoints have a much lower rate.</p><h2 id="example-headers" tabindex="-1">Example headers: <a class="header-anchor" href="#example-headers" aria-label="Permalink to &quot;Example headers:&quot;">​</a></h2><p>Generally the API will have a large rate limit.</p><p>The below example shows a rate limit of 2000 requests, with 1999 remaining, and the reset time in epoch seconds.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x-ratelimit-limit	    2000</span></span>
<span class="line"><span>x-ratelimit-remaining	1999</span></span>
<span class="line"><span>x-ratelimit-reset	    1697448304</span></span></code></pre></div><p>Some endpoints may have a lower rate limit.</p><p>For example authentication related endpoints may have a rate limit of 12 requests.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x-ratelimit-limit	    12</span></span>
<span class="line"><span>x-ratelimit-remaining	11</span></span>
<span class="line"><span>x-ratelimit-reset	    1697448304</span></span></code></pre></div><p>If you get rate limited by the edge, you won&#39;t receive a reset time, but you will receive a window period.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x-ratelimit-limit	    2000</span></span>
<span class="line"><span>x-ratelimit-remaining	0</span></span>
<span class="line"><span>x-ratelimit-window      300</span></span></code></pre></div>`,16)])])}const u=t(n,[["render",r]]);export{c as __pageData,u as default};
